    "note.hidetag": "Hidetag ऐसा संदेश भेजता है जो समूह के हर सदस्य को बिना @नाम दिखाए मेंशन करता है, इसलिए सभी को सूचना मिलती है। इसे केवल उन समूहों में उपयोग करें जिन्हें आप चलाते हैं या जहाँ सदस्य सहमत हों।",
